source4='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    out = [row[:] for row in grid]

    def fill(r, c):
        if grid[r][c] == background:
            out[r][c] = 2

    for c in range(c0, c1 + 1):
        fill(r0, c)
        fill(r1, c)
    for r in range(r0, r1 + 1):
        fill(r, c0)
        fill(r, c1)

    for r in range(r0 + 1, r1):
        run = 0
        has_long_run = False
        for c in range(c0, c1 + 1):
            run = run + 1 if grid[r][c] != background else 0
            has_long_run |= run >= 3
        if has_long_run:
            for c in range(c0, c1 + 1):
                fill(r, c)

    for c in range(c0 + 1, c1):
        run = 0
        has_long_run = False
        for r in range(r0, r1 + 1):
            run = run + 1 if grid[r][c] != background else 0
            has_long_run |= run >= 3
        if has_long_run:
            for r in range(r0, r1 + 1):
                fill(r, c)

    return out
'''
